<?php require '../config.php';admin();$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT * FROM tickets WHERE id=?");$s->execute([$id]);$t=$s->fetch();if(!$t)exit('Ticket not found');$f=flash();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($t['subject'])?></title><link rel="stylesheet" href="../assets/style.css"></head><body class="staff"><aside class="staffside"><a class="logo" href="../index.php"><span>desk</span>flow</a><a class="sideactive" href="index.php">Inbox</a><a href="articles.php">Knowledge base</a><a href="../index.php">View portal</a><a href="logout.php">Sign out</a></aside><main class="staffmain detailstaff"><a class="back" href="index.php">← Inbox</a><?php if($f):?><div class="saved"><?=e($f)?></div><?php endif;?><div class="split"><section class="conversation"><small><?=e($t['ticket_no'])?></small><h1><?=e($t['subject'])?></h1><div class="person"><div class="initial"><?=e(strtoupper(substr($t['name'],0,1)))?></div><div><b><?=e($t['name'])?></b><span><?=e($t['email'])?> · <?=e($t['category'])?></span></div></div><div class="msg"><p><?=nl2br(e($t['message']))?></p><small><?=e(date('M j, Y H:i',strtotime($t['created_at'])))?></small></div><?php if($t['agent_reply']):?><div class="agentmsg"><b>Your reply</b><p><?=nl2br(e($t['agent_reply']))?></p></div><?php endif;?></section><aside class="ticketpanel"><small>UPDATE TICKET</small><form method="post" action="update.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$t['id']?>"><label>Status<select name="status"><?php foreach(['open','pending','solved','closed'] as $x):?><option <?=$t['status']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></label><label>Priority<select name="priority"><?php foreach(['low','normal','high','urgent'] as $x):?><option <?=$t['priority']===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></label><label>Reply to customer<textarea name="reply" rows="8" placeholder="Write a helpful response..."><?=e($t['agent_reply']??'')?></textarea></label><button>Save & update</button></form></aside></div></main></body></html>